//! `axeyum.cas.certify.ansatz` — bounded-degree ideal membership by linear
//! ansatz, and the linear-elimination identity the Groebner route falls back to.
//!
//! Both routes here are *cofactor* routes: they answer "is `target` in the ideal
//! generated by `generators`" by producing the cofactors, which is the whole
//! point — a caller re-expands `sum(cofactors[i] * generators[i])` and compares,
//! and `combination` is that re-expansion as a public function.
//!
//! The distinction this module refuses to blur, and the one the Rust doc calls
//! out in as many words: **`NotInDegree` is a decision about the degree slice,
//! never about the ideal.** It must not render as "unknown", and it must not
//! render as "not a member". `Declined` is the budget refusing to build a
//! system, which is the honest unknown.

use axeyum_cas::cofactor_ansatz::{
    AnsatzDecline as CasAnsatzDecline, AnsatzLimits as CasAnsatzLimits,
    AnsatzOutcome as CasAnsatzOutcome,
};
use axeyum_cas::linear_elim::{
    LinearBlock as CasLinearBlock, LinearElimination as CasLinearElimination,
};
use pyo3::prelude::*;
use pyo3::types::{PyAny, PyModule};

use crate::cas::poly::MvPoly;

/// Explicit ceilings for a bounded-degree membership search.
///
/// Only `max_cofactor_degree` is a mathematical parameter — the slice of the
/// ideal being searched. The other two exist so a pathological generator list
/// cannot allocate an enormous matrix before anyone notices.
#[cfg_attr(
    feature = "stub-gen",
    pyo3_stub_gen::derive::gen_stub_pyclass(module = "axeyum._native.cas.certify.ansatz")
)]
#[pyclass(frozen, from_py_object, module = "axeyum", name = "AnsatzLimits")]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct AnsatzLimits {
    inner: CasAnsatzLimits,
}

#[cfg_attr(feature = "stub-gen", pyo3_stub_gen::derive::gen_stub_pymethods)]
#[pymethods]
impl AnsatzLimits {
    /// Ceilings, defaulting to the Rust `AnsatzLimits::geometry()` verbatim:
    /// `max_cofactor_degree=3`, `max_columns=20_000`, `max_rows=200_000`.
    #[new]
    #[pyo3(signature = (max_cofactor_degree = 3, max_columns = 20_000, max_rows = 200_000))]
    fn new(max_cofactor_degree: u32, max_columns: usize, max_rows: usize) -> AnsatzLimits {
        AnsatzLimits {
            inner: CasAnsatzLimits {
                max_cofactor_degree,
                max_columns,
                max_rows,
            },
        }
    }

    /// The ceilings sized for the geometry corpus.
    #[staticmethod]
    fn geometry() -> AnsatzLimits {
        AnsatzLimits {
            inner: CasAnsatzLimits::geometry(),
        }
    }

    /// The largest total degree an individual cofactor may have.
    #[getter]
    fn max_cofactor_degree(&self) -> u32 {
        self.inner.max_cofactor_degree
    }

    /// The largest number of unknowns admitted.
    #[getter]
    fn max_columns(&self) -> usize {
        self.inner.max_columns
    }

    /// The largest number of equations admitted.
    #[getter]
    fn max_rows(&self) -> usize {
        self.inner.max_rows
    }

    fn __eq__(&self, other: &Bound<'_, PyAny>) -> bool {
        // `cast` + `get`, never `extract`: `extract` on a `#[pyclass]` CLONES the
        // whole wrapped value to compare it and then drops it.
        other
            .cast::<AnsatzLimits>()
            .is_ok_and(|other| other.get().inner == self.inner)
    }

    fn __repr__(&self) -> String {
        format!(
            "AnsatzLimits(max_cofactor_degree={}, max_columns={}, max_rows={})",
            self.inner.max_cofactor_degree, self.inner.max_columns, self.inner.max_rows
        )
    }
}

/// The result of a bounded-degree membership search.
///
/// Tier C — outcome. `kind` is one of three genuinely different answers:
///
/// * `"Solved"` — cofactors exist at `degree`, and the producer re-expanded them
///   before returning, so a wrong solve cannot leave the Rust module;
/// * `"NotInDegree"` — **decided**: no representation exists with every cofactor
///   of degree at most `bound`. A statement about the degree slice, not about
///   the ideal;
/// * `"Declined"` — no system was built at all, with the budget that refused.
#[cfg_attr(
    feature = "stub-gen",
    pyo3_stub_gen::derive::gen_stub_pyclass(module = "axeyum._native.cas.certify.ansatz")
)]
#[pyclass(frozen, from_py_object, module = "axeyum", name = "AnsatzOutcome")]
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AnsatzOutcome {
    inner: CasAnsatzOutcome,
    generators: Vec<axeyum_cas::MvPoly>,
    target: axeyum_cas::MvPoly,
}

#[cfg_attr(feature = "stub-gen", pyo3_stub_gen::derive::gen_stub_pymethods)]
#[pymethods]
impl AnsatzOutcome {
    /// `"Solved"`, `"NotInDegree"` or `"Declined"`.
    #[getter]
    fn kind(&self) -> &'static str {
        match self.inner {
            CasAnsatzOutcome::Solved { .. } => "Solved",
            CasAnsatzOutcome::NotInDegree(_) => "NotInDegree",
            CasAnsatzOutcome::Declined(_) => "Declined",
        }
    }

    /// The cofactors, positionally aligned with the generators, or `None`.
    #[getter]
    fn cofactors(&self) -> Option<Vec<MvPoly>> {
        match &self.inner {
            CasAnsatzOutcome::Solved { cofactors, .. } => Some(MvPoly::wrap_vec(cofactors)),
            _ => None,
        }
    }

    /// The degree at which the system became solvable, or `None`.
    #[getter]
    fn degree(&self) -> Option<u32> {
        match self.inner {
            CasAnsatzOutcome::Solved { degree, .. } => Some(degree),
            _ => None,
        }
    }

    /// The degree bound the search decided against, or `None`.
    ///
    /// Present only for `"NotInDegree"`, and reading it is how a caller states
    /// the decision correctly: *not in the ideal at cofactor degree at most
    /// this*, which is weaker than *not in the ideal*.
    #[getter]
    fn bound(&self) -> Option<u32> {
        match self.inner {
            CasAnsatzOutcome::NotInDegree(bound) => Some(bound),
            _ => None,
        }
    }

    /// `"Columns"`, `"Rows"` or `"Overflow"` for a decline, else `None`.
    #[getter]
    fn decline(&self) -> Option<&'static str> {
        match self.inner {
            CasAnsatzOutcome::Declined(CasAnsatzDecline::Columns) => Some("Columns"),
            CasAnsatzOutcome::Declined(CasAnsatzDecline::Rows) => Some("Rows"),
            CasAnsatzOutcome::Declined(CasAnsatzDecline::Overflow) => Some("Overflow"),
            _ => None,
        }
    }

    /// The generators the search was run against.
    #[getter]
    fn generators(&self) -> Vec<MvPoly> {
        MvPoly::wrap_vec(&self.generators)
    }

    /// The target the search was run against.
    #[getter]
    fn target(&self) -> MvPoly {
        MvPoly::wrap(self.target.clone())
    }

    /// Re-expands the cofactors and compares with the target, returning the
    /// report.
    ///
    /// The count is the number of nonzero cofactors the identity rests on, and
    /// it is reported separately from the verdict for a measured reason: the
    /// geometry corpus contains conclusions that are identically zero with an
    /// **empty** cofactor list, where "the identity holds" is true and
    /// establishes nothing.
    fn check(&self, py: Python<'_>) -> AnsatzCheckReport {
        let CasAnsatzOutcome::Solved { cofactors, .. } = &self.inner else {
            return AnsatzCheckReport {
                identity_holds: false,
                nonzero_cofactors: 0,
                attempted: false,
            };
        };
        let (identity_holds, nonzero_cofactors) = py.detach(|| {
            let expanded = axeyum_cas::linear_elim::combination(cofactors, &self.generators);
            (
                expanded.is_some_and(|expanded| expanded == self.target),
                cofactors
                    .iter()
                    .filter(|cofactor| !cofactor.is_zero())
                    .count(),
            )
        });
        AnsatzCheckReport {
            identity_holds,
            nonzero_cofactors,
            attempted: true,
        }
    }

    fn __repr__(&self) -> String {
        format!("AnsatzOutcome({})", self.kind())
    }
}

/// What the ansatz re-expansion established.
#[cfg_attr(
    feature = "stub-gen",
    pyo3_stub_gen::derive::gen_stub_pyclass(module = "axeyum._native.cas.certify.ansatz")
)]
#[pyclass(frozen, from_py_object, module = "axeyum", name = "AnsatzCheckReport")]
#[derive(Debug, Clone, Copy)]
pub struct AnsatzCheckReport {
    identity_holds: bool,
    nonzero_cofactors: usize,
    attempted: bool,
}

#[cfg_attr(feature = "stub-gen", pyo3_stub_gen::derive::gen_stub_pymethods)]
#[pymethods]
impl AnsatzCheckReport {
    /// Whether `sum(cofactors[i] * generators[i])` re-expanded to the target.
    #[getter]
    fn identity_holds(&self) -> bool {
        self.identity_holds
    }

    /// How many cofactors are nonzero — the size of the certificate.
    ///
    /// Zero with `identity_holds` true means the target was itself zero: the
    /// identity is vacuous and nothing was established.
    #[getter]
    fn nonzero_cofactors(&self) -> usize {
        self.nonzero_cofactors
    }

    /// Whether there were cofactors to check at all.
    #[getter]
    fn attempted(&self) -> bool {
        self.attempted
    }

    /// Whether the check both ran and established something non-vacuous.
    fn accepted(&self) -> bool {
        self.attempted && self.identity_holds && self.nonzero_cofactors > 0
    }

    fn __repr__(&self) -> String {
        format!(
            "AnsatzCheckReport(identity_holds={}, nonzero_cofactors={}, accepted={})",
            self.identity_holds,
            self.nonzero_cofactors,
            self.accepted()
        )
    }
}

/// One square subsystem of the generators, solved by Cramer's rule.
#[cfg_attr(
    feature = "stub-gen",
    pyo3_stub_gen::derive::gen_stub_pyclass(module = "axeyum._native.cas.certify.ansatz")
)]
#[pyclass(frozen, from_py_object, module = "axeyum", name = "LinearBlock")]
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LinearBlock {
    inner: CasLinearBlock,
}

#[cfg_attr(feature = "stub-gen", pyo3_stub_gen::derive::gen_stub_pymethods)]
#[pymethods]
impl LinearBlock {
    /// A block from its parts, so a caller can pin a decomposition rather than
    /// inherit the heuristic.
    #[new]
    fn new(unknowns: Vec<String>, rows: Vec<usize>, determinant: &MvPoly) -> LinearBlock {
        LinearBlock {
            inner: CasLinearBlock {
                unknowns,
                rows,
                determinant: determinant.inner().clone(),
            },
        }
    }

    /// The variables this block eliminates, ascending.
    #[getter]
    fn unknowns(&self) -> Vec<String> {
        self.inner.unknowns.clone()
    }

    /// Indices into the caller's generator list.
    #[getter]
    fn rows(&self) -> Vec<usize> {
        self.inner.rows.clone()
    }

    /// `det(M)`, never the zero polynomial.
    #[getter]
    fn determinant(&self) -> MvPoly {
        MvPoly::wrap(self.inner.determinant.clone())
    }

    fn __eq__(&self, other: &Bound<'_, PyAny>) -> bool {
        // `cast` + `get`, never `extract`: `extract` on a `#[pyclass]` CLONES the
        // whole wrapped value to compare it and then drops it.
        other
            .cast::<LinearBlock>()
            .is_ok_and(|other| other.get().inner == self.inner)
    }

    fn __repr__(&self) -> String {
        format!(
            "LinearBlock(unknowns={}, rows={})",
            self.inner.unknowns.len(),
            self.inner.rows.len()
        )
    }
}

/// The identity produced by `eliminate`.
///
/// Tier C — certificate. The invariant, and the only thing to rely on:
///
/// ```text
/// multiplier * target == residue + sum(cofactors[i] * generators[i])
/// ```
///
/// with `residue` free of every eliminated unknown and `multiplier` the product
/// of `blocks[i].determinant ** powers[i]`. `check` re-derives exactly that.
#[cfg_attr(
    feature = "stub-gen",
    pyo3_stub_gen::derive::gen_stub_pyclass(module = "axeyum._native.cas.certify.ansatz")
)]
#[pyclass(frozen, from_py_object, module = "axeyum", name = "LinearElimination")]
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LinearElimination {
    inner: CasLinearElimination,
    generators: Vec<axeyum_cas::MvPoly>,
    target: axeyum_cas::MvPoly,
}

#[cfg_attr(feature = "stub-gen", pyo3_stub_gen::derive::gen_stub_pymethods)]
#[pymethods]
impl LinearElimination {
    /// The subsystems inverted, in application order.
    #[getter]
    fn blocks(&self) -> Vec<LinearBlock> {
        self.inner
            .blocks
            .iter()
            .cloned()
            .map(|inner| LinearBlock { inner })
            .collect()
    }

    /// The determinant power each block contributed to `multiplier`.
    #[getter]
    fn powers(&self) -> Vec<u32> {
        self.inner.powers.clone()
    }

    /// `prod(blocks[i].determinant ** powers[i])`.
    #[getter]
    fn multiplier(&self) -> MvPoly {
        MvPoly::wrap(self.inner.multiplier.clone())
    }

    /// One cofactor per generator, positionally aligned.
    #[getter]
    fn cofactors(&self) -> Vec<MvPoly> {
        MvPoly::wrap_vec(&self.inner.cofactors)
    }

    /// What linear algebra could not remove.
    #[getter]
    fn residue(&self) -> MvPoly {
        MvPoly::wrap(self.inner.residue.clone())
    }

    /// The generators the elimination ran against.
    #[getter]
    fn generators(&self) -> Vec<MvPoly> {
        MvPoly::wrap_vec(&self.generators)
    }

    /// The target the elimination ran against.
    #[getter]
    fn target(&self) -> MvPoly {
        MvPoly::wrap(self.target.clone())
    }

    /// Re-derives `multiplier * target == residue + combination(...)` without
    /// trusting the producer, returning the report.
    fn check(&self, py: Python<'_>) -> LinearEliminationCheckReport {
        let (identity_holds, multiplier_matches, nonzero_cofactors) = py.detach(|| {
            let left = self.inner.multiplier.mul(&self.target);
            let combination =
                axeyum_cas::linear_elim::combination(&self.inner.cofactors, &self.generators);
            let identity_holds = match (left, combination) {
                (Some(left), Some(combination)) => self
                    .inner
                    .residue
                    .add(&combination)
                    .is_some_and(|right| right == left),
                _ => false,
            };
            let mut rebuilt = axeyum_cas::MvPoly::constant(axeyum_ir::Rational::integer(1));
            let mut multiplier_matches = true;
            for (block, power) in self.inner.blocks.iter().zip(&self.inner.powers) {
                for _ in 0..*power {
                    if let Some(next) = rebuilt.mul(&block.determinant) {
                        rebuilt = next;
                    } else {
                        multiplier_matches = false;
                        break;
                    }
                }
            }
            multiplier_matches = multiplier_matches && rebuilt == self.inner.multiplier;
            let nonzero_cofactors = self
                .inner
                .cofactors
                .iter()
                .filter(|cofactor| !cofactor.is_zero())
                .count();
            (identity_holds, multiplier_matches, nonzero_cofactors)
        });
        LinearEliminationCheckReport {
            identity_holds,
            multiplier_matches,
            nonzero_cofactors,
            blocks: self.inner.blocks.len(),
        }
    }

    fn __repr__(&self) -> String {
        format!(
            "LinearElimination(blocks={}, cofactors={})",
            self.inner.blocks.len(),
            self.inner.cofactors.len()
        )
    }
}

/// What the linear-elimination re-derivation established.
#[cfg_attr(
    feature = "stub-gen",
    pyo3_stub_gen::derive::gen_stub_pyclass(module = "axeyum._native.cas.certify.ansatz")
)]
#[pyclass(
    frozen,
    from_py_object,
    module = "axeyum",
    name = "LinearEliminationCheckReport"
)]
#[derive(Debug, Clone, Copy)]
pub struct LinearEliminationCheckReport {
    identity_holds: bool,
    multiplier_matches: bool,
    nonzero_cofactors: usize,
    blocks: usize,
}

#[cfg_attr(feature = "stub-gen", pyo3_stub_gen::derive::gen_stub_pymethods)]
#[pymethods]
impl LinearEliminationCheckReport {
    /// Whether `multiplier * target == residue + combination(...)`.
    #[getter]
    fn identity_holds(&self) -> bool {
        self.identity_holds
    }

    /// Whether `multiplier` really is the product of the block determinants
    /// raised to the reported powers.
    ///
    /// Checked separately because the identity alone would accept a multiplier
    /// the blocks do not justify.
    #[getter]
    fn multiplier_matches(&self) -> bool {
        self.multiplier_matches
    }

    /// How many cofactors are nonzero.
    #[getter]
    fn nonzero_cofactors(&self) -> usize {
        self.nonzero_cofactors
    }

    /// How many blocks were inverted.
    #[getter]
    fn blocks(&self) -> usize {
        self.blocks
    }

    /// Whether both obligations held.
    fn accepted(&self) -> bool {
        self.identity_holds && self.multiplier_matches
    }

    fn __repr__(&self) -> String {
        format!(
            "LinearEliminationCheckReport(identity_holds={}, multiplier_matches={}, \
             blocks={}, nonzero_cofactors={})",
            self.identity_holds, self.multiplier_matches, self.blocks, self.nonzero_cofactors
        )
    }
}

/// Searches for `target == sum(u[i] * generators[i])` with every `deg(u[i])` at
/// most `d`, for the least `d` that admits one.
///
/// Tier C — producer. Degrees are tried ascending, so the representation found
/// is the one of least cofactor degree.
///
/// # Errors
///
/// Propagates the per-element extraction error.
#[cfg_attr(
    feature = "stub-gen",
    pyo3_stub_gen::derive::gen_stub_pyfunction(module = "axeyum._native.cas.certify.ansatz")
)]
#[pyfunction]
#[pyo3(signature = (generators, target, limits = None))]
fn cofactors_by_ansatz(
    py: Python<'_>,
    generators: &Bound<'_, PyAny>,
    target: &MvPoly,
    limits: Option<AnsatzLimits>,
) -> PyResult<AnsatzOutcome> {
    let generators = MvPoly::vec_from_py(generators)?;
    let limits = limits.map_or_else(CasAnsatzLimits::geometry, |limits| limits.inner);
    let target = target.inner().clone();
    let inner = py
        .detach(|| axeyum_cas::cofactor_ansatz::cofactors_by_ansatz(&generators, &target, limits));
    Ok(AnsatzOutcome {
        inner,
        generators,
        target,
    })
}

/// The linear-elimination identity for `target` against `generators`, or `None`.
///
/// Tier C — producer. `None` is *no block decomposition applied* or exact
/// overflow.
///
/// # Errors
///
/// Propagates the per-element extraction error.
#[cfg_attr(
    feature = "stub-gen",
    pyo3_stub_gen::derive::gen_stub_pyfunction(module = "axeyum._native.cas.certify.ansatz")
)]
#[pyfunction]
fn eliminate(
    py: Python<'_>,
    generators: &Bound<'_, PyAny>,
    target: &MvPoly,
) -> PyResult<Option<LinearElimination>> {
    let generators = MvPoly::vec_from_py(generators)?;
    let target = target.inner().clone();
    let inner = py.detach(|| axeyum_cas::linear_elim::eliminate(&generators, &target));
    Ok(inner.map(|inner| LinearElimination {
        inner,
        generators,
        target,
    }))
}

/// `eliminate` against a caller-chosen block decomposition.
///
/// Tier C — producer. Exposed so a caller can pin the decomposition rather than
/// inherit the heuristic, and so the heuristic itself is testable against a
/// hand-written answer.
///
/// # Errors
///
/// Propagates the per-element extraction error.
#[cfg_attr(
    feature = "stub-gen",
    pyo3_stub_gen::derive::gen_stub_pyfunction(module = "axeyum._native.cas.certify.ansatz")
)]
#[pyfunction]
fn eliminate_blocks(
    py: Python<'_>,
    generators: &Bound<'_, PyAny>,
    target: &MvPoly,
    blocks: Vec<LinearBlock>,
) -> PyResult<Option<LinearElimination>> {
    let generators = MvPoly::vec_from_py(generators)?;
    let target = target.inner().clone();
    let blocks: Vec<CasLinearBlock> = blocks.into_iter().map(|block| block.inner).collect();
    let inner =
        py.detach(|| axeyum_cas::linear_elim::eliminate_blocks(&generators, &target, blocks));
    Ok(inner.map(|inner| LinearElimination {
        inner,
        generators,
        target,
    }))
}

/// The heuristic block decomposition of `generators` for `target`.
///
/// Tier R: a pure function.
///
/// # Errors
///
/// Propagates the per-element extraction error.
#[cfg_attr(
    feature = "stub-gen",
    pyo3_stub_gen::derive::gen_stub_pyfunction(module = "axeyum._native.cas.certify.ansatz")
)]
#[pyfunction]
fn detect_linear_blocks(
    py: Python<'_>,
    generators: &Bound<'_, PyAny>,
    target: &MvPoly,
) -> PyResult<Vec<LinearBlock>> {
    let generators = MvPoly::vec_from_py(generators)?;
    let target = target.inner().clone();
    Ok(py
        .detach(|| axeyum_cas::linear_elim::detect_linear_blocks(&generators, &target))
        .into_iter()
        .map(|inner| LinearBlock { inner })
        .collect())
}

/// `sum(cofactors[i] * generators[i])`, expanded — the re-expansion checker.
///
/// Tier R: a pure function, and the public form of the bookkeeping invariant.
/// `None` is exact `i128` overflow.
///
/// # Errors
///
/// Propagates the per-element extraction error.
#[cfg_attr(
    feature = "stub-gen",
    pyo3_stub_gen::derive::gen_stub_pyfunction(module = "axeyum._native.cas.certify.ansatz")
)]
#[pyfunction]
fn combination(
    cofactors: &Bound<'_, PyAny>,
    generators: &Bound<'_, PyAny>,
) -> PyResult<Option<MvPoly>> {
    let cofactors = MvPoly::vec_from_py(cofactors)?;
    let generators = MvPoly::vec_from_py(generators)?;
    Ok(MvPoly::wrap_option(axeyum_cas::linear_elim::combination(
        &cofactors,
        &generators,
    )))
}

/// Registers the `ansatz` route on `parent`.
///
/// # Errors
///
/// Propagates any Python error raised while creating or populating the module.
pub(crate) fn register(parent: &Bound<'_, PyModule>) -> PyResult<()> {
    let module = PyModule::new(parent.py(), "axeyum._native.cas.certify.ansatz")?;
    module.add_class::<AnsatzLimits>()?;
    module.add_class::<AnsatzOutcome>()?;
    module.add_class::<AnsatzCheckReport>()?;
    module.add_class::<LinearBlock>()?;
    module.add_class::<LinearElimination>()?;
    module.add_class::<LinearEliminationCheckReport>()?;
    module.add_function(wrap_pyfunction!(cofactors_by_ansatz, &module)?)?;
    module.add_function(wrap_pyfunction!(eliminate, &module)?)?;
    module.add_function(wrap_pyfunction!(eliminate_blocks, &module)?)?;
    module.add_function(wrap_pyfunction!(detect_linear_blocks, &module)?)?;
    module.add_function(wrap_pyfunction!(combination, &module)?)?;
    parent.add("ansatz", &module)?;
    Ok(())
}
